{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "The closest analogue, ibrutinib (Morgan similarity 0.37), is directly CNS-penetrant in mice with a brain-to-plasma ratio of 0.7, indicating meaningful brain exposure despite possible efflux.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "In patients, ibrutinib showed a protein-binding-corrected CSF/plasma ratio of about 29%, supporting significant CNS penetration for this acrylamide-piperidine chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A structurally related acrylamide-piperidine BTK inhibitor had an acceptable rat Kp,uu of 0.37, demonstrating that this scaffold can achieve meaningful unbound brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Related BTK inhibitors (tolebrutinib, fenebrutinib, evobrutinib) were detected in non-human primate CSF at pharmacologically relevant doses, supporting CNS access for this inhibitor class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Sotorasib, a lower-similarity acrylamide-containing molecule, had brain accumulation strongly restricted by ABCB1 in mice, providing a contradictory efflux-liability signal.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass: despite physicochemical concerns about high MW/logP and possible efflux, the closest and multiple related acrylamide-piperidine kinase inhibitors demonstrate meaningful CNS exposure; the query's zero HBD and lower TPSA may partly offset these liabilities, while the main contradictory efflux example is structurally more distant.",
  "evidence_gaps": [
    "No direct brain, CSF, or Kp,uu data exist for the query molecule.",
    "The highest similarity to a direct CNS-penetration measurement is only 0.37.",
    "P-gp/BCRP substrate status and unbound brain exposure of the query are not experimentally defined.",
    "High lipophilicity and protein binding may reduce free brain concentrations despite total brain uptake."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

